public class TarUtils_parseOctal_TriageGen1Test {





















    @Test
    public void testParseOctal_StrictLeading() {
        // The code skips ' ', but NOT 0.
        // If buffer[start] is 0, it hits: if (currentByte < '0' || currentByte >= '7')
        // 0 is < '0'. So it throws.
        // Therefore, leading NULs in the buffer are only okay if they are part of the "allNUL" check.
        byte[] buffer = " 0755 ".getBytes(); 
        long result = TarUtils.parseOctal(buffer, 0, 6);
        assertEquals(493L, result);
    }




}

