 * Unit tests for TarUtils.parseOctal to maximize branch and line coverage.
 */
public class TarUtils_parseOctal_TriageGen1Test {

























    @Test(expected = IllegalArgumentException.class)
    public void testParseOctal_DigitSevenIsInvalid() {
        // The code says: if (currentByte < '0' || currentByte >= '7')
        // This means '7' IS invalid. Octal digits are 0-7, but the code uses '7' as the exclusive upper bound.
        // Let's check: if currentByte is '7', '7' >= '7' is true, so it throws.
        // So this method only parses digits 0 through 6? 
        // That's unusual for octal, but we must test the code as written.
        byte[] buffer = "7 ".getBytes();
        TarUtils.parseOctal(buffer, 0, 2);
    }
}
